import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem74 preserva operação identidade e idempotência',()=>{for(const [id,titulo] of [['F8RXRAtxM4QOCg5hbFh9','Chaleira Eletrica Atacama Inox 1,8 Litros 220v Unitermi Cor Cinza-escuro'],['f9oPhNSAdi4gqtwPJbJh','Mixer Philco Pmx2000 3 Em 1 Inox 800w cor preto'],['FeYsjVKPd6nzosN6U8QB','Uomini Black Desodorante Colônia O Boticário - 100ml']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Capa para '+titulo,comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/ideal|garantid|profunda intensidade|impede.*odores/i);}});
